class NomSistemaPago extends BaseNomSistemaPago {

    /**
     * Obtener un listado de los datos de los sistemas de pago dado un identificador de forma de pago.
     * 
     * @param int $inicio       Inicio de la busqueda.
     * @param int $limite       Limite maximo de la busqueda.
     * @param int $idformapago  Identificador de la forma de pago.
	 *
     * @return array Listado de los datos de los sistemas de pago.
     */
    public static function obtenerListadoSistemasPago($inicio = 0, $limite = 10, $idformapago) {

        //Devolviendo el listado de sistemas de pago en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomSistemaPago')
                ->where('idformapago = ?', $idformapago)
                ->limit($limite)
                ->offset($inicio)
				->orderBy('denominacion')
                ->fetchArray();
    }

    /**
     * Obtener la cantidad total de sistemas de pago.
     * 
     * @param int $idformapago  	Identificador de la forma de pago.
	 *
     * @return int      			Cantidad total de sistemas de pago.
     */
    public static function obtenerCantidadTotalSistemasPago($idformapago) {

        //Devolviendo la cantidad total de sistemas de pago.
        return Doctrine_Query::create()->select('COUNT(idsistemapago) AS cantidad')
                        ->from('NomSistemaPago')
                        ->where('idformapago = ?', $idformapago)
                        ->fetchOne()
                        ->cantidad;
    }

    /**
     * Obtener el sistema de pago dado el identificador.
     * 
     * @param $idsistema        Identificador del sistema de pago.
     * @return NomSistemaPago    Objeto sistemade pago (clase del dominio).
     */
    public static function obtenerObjSistemaPagoDadoId($idsistema) {
        return Doctrine::getTable('NomSistemaPago')->find($idsistema);
    }
    
	/**
     * Obtener si existe un sistema de pago a partir de la denominación.
     * 
	 * @param int $idforma    		Identificador de la forma de pago.
	 * @param int $idsistema    	Identificador del sistema de pago.
     * @param string $denom    	 	Denominación del sistema de pago.
	 *
     * @return boolean    			Si existe el sistema de pago.
     */
    public static function existeSistemaPago($idforma, $idsistema, $denom) {
		
		$query = Doctrine_Query::create()->select('COUNT(idsistemapago) AS cantidad')
                        ->from('NomSistemaPago')
						->where("idformapago = ? and denominacion ilike ?", array($idforma, $denom));
		if($idsistema){
			$query->addWhere('idsistemapago <> ?', $idsistema);
		}		
		
		return    $query->fetchOne()->cantidad;
     }
	 
	 
	 
	 
	 
	 
	 
	 
	 
	
	
	
	
	
	
	
	
/************************VER DESDE AQUI******************************************/	
	 public static function obtenerListadoTodosSistemasPago($inicio = 0, $limite = 10) {

        //Devolviendo el listado de sistemas de pago en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomSistemaPago')
                ->limit($limite)
                ->offset($inicio)
                ->fetchArray();
    }
	
    public static function obtenerListadoSistemasPagoActivos($idformapago) {

        //Devolviendo el listado de sistemas de pago en forma de arreglo.
        return Doctrine_Query::create()
				->select("idsistemapago, 'S-'||idsistemapago as id, idsistemapago as _id, denominacion, denominacion as text, fechainicio, fechafin, descripcion")
                ->from('NomSistemaPago')
                ->where('idformapago = ? and (fechafin is null or fechafin <= now())', array($idformapago))
                ->fetchArray();
    }
    
    public static function existeDenominacionSistemaPago($denominacion) {
        //Devolviendo la cantidad total de los salarios especificos.
        $query = new Doctrine_Query ();
        $result = $query->from('NomSistemaPago p')
                ->where("p.denominacion=?", array($denominacion))
                ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
                ->execute();
          if(count($result)){
		   return 1;	
	         }else{
		   return 0;
		 }
     }
     
    public static function obtenerDenomXId($idsistemapago) {
        return Doctrine_Query::create()->select('p.denominacion AS denominacion')
                        ->from('NomSistemaPago p')
                        ->where('p.idsistemapago = ?', array($idsistemapago))
                        ->fetchOne()
                        ->denominacion;
   }

}
